(() => {
  'use strict';
  const A=Academy, $=s=>document.querySelector(s), main=$('#main');
  const key='qqbot-academy-v1', blank=()=>({done:[],practice:{},quiz:{},real:{},answers:{},last:0});
  let state=blank(), storageOK=true, sim=null, labLesson=null, historyIndex=0, toastTimer;
  try { const p=JSON.parse(localStorage.getItem(key)||'null'); if(p && Array.isArray(p.done) && p.practice && p.quiz && p.real && p.answers) state={...blank(),...p,done:p.done.filter(i=>Number.isInteger(i)&&i>=0&&i<A.lessons.length)}; } catch { storageOK=false; }
  const e=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  function save() { try { localStorage.setItem(key,JSON.stringify(state)); storageOK=true; } catch { storageOK=false; } $('#save-status').textContent=storageOK?'进度已保存在此浏览器':'浏览器未允许保存，请导出进度'; }
  function toast(s) { $('#toast').textContent=s; $('#toast').classList.add('visible'); clearTimeout(toastTimer); toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3000); }
  const label=i=>String(i+1).padStart(2,'0');
  const total=()=>state.done.length;
  const realDone=()=>A.lessons[6].real.every((_,i)=>state.real[`6-${i}`]===true);
  const button=(text,href,cls='primary')=>`<a class="button ${cls}" href="${href}">${text}</a>`;
  function nav() {
    const route=location.hash.slice(1)||'home';
    $('#nav').innerHTML=[['home','⌂','学习概览'],['lab','>_','终端练习场'],['reference','▤','命令速查'],['trouble','↺','遇到问题']].map(([id,icon,text])=>`<a href="#${id}" class="nav-item ${route===id?'active':''}" ${route===id?'aria-current="page"':''}><span class="nav-symbol">${icon}</span>${text}${id==='home'?'<span class="nav-mini">开始</span>':''}</a>`).join('');
    $('#course-nav').innerHTML=A.lessons.map((l,i)=>`<a class="course-item ${route.startsWith('lesson/'+i)?'active':''}" href="#lesson/${i}/read" ${route.startsWith('lesson/'+i)?'aria-current="page"':''}><span class="course-number ${state.done.includes(i)?'checked':''}">${state.done.includes(i)?'✓':label(i)}</span><span>${e(l.title)}</span></a>`).join('');
  }
  function header(eyebrow,title,sub) { return `<div class="page-head"><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="lead">${sub}</p></div>`; }
  function code(command) { return `<div class="code-copy"><code>${e(command)}</code><button class="copy" data-copy="${e(command)}" aria-label="复制命令 ${e(command)}">复制</button></div>`; }
  function home() {
    const next=A.lessons.findIndex((_,i)=>!state.done.includes(i));
    const idx=next<0?6:Math.min(6,Math.max(0,Number(state.last)||next)), progress=Math.round(total()/7*100);
    return `<section class="hero"><div class="hero-copy"><div class="eyebrow"><span class="tiny-line"></span> 每天 20 分钟 · 从零开始</div><h1>把服务器，<br>变成你<span class="underline">会用的工具。</span></h1><p>从第一次打开终端，到自己登录 QQ。<br>一步一步学，下一次不用等 AI 帮你操作。</p><div class="hero-actions">${button(total()?'继续我的学习 <span>↗</span>':'开始第一课 <span>↗</span>',`#lesson/${total()?idx:0}/read`)}<a class="text-link" href="#lab">先试试模拟终端 →</a></div><div class="hero-facts"><span>✓ 无需购买新服务器</span><span>✓ 用你自己的 QQbot 练习</span></div></div><div class="hero-art" aria-label="Mac 通过 SSH 管理云端 QQbot 的示意图"><div class="orbit orbit-a"></div><div class="orbit orbit-b"></div><span class="art-plus p1">+</span><span class="art-plus p2">+</span><div class="cloud-tag"><span class="green-dot"></span> 云端一直在工作</div><div class="server-box"><div class="server-top">UBUNTU SERVER <span>●</span></div><div class="server-slot"><i></i><i></i><span>napcat</span><b>↔ QQ</b></div><div class="server-slot"><i></i><i></i><span>qqbot</span><b>↔ 模型</b></div><div class="server-lines"><i></i><i></i><i></i><i></i><i></i></div></div><div class="tunnel-line"></div><div class="ssh-pill">SSH · 加密连接</div><div class="mini-terminal"><div class="dots"><i></i><i></i><i></i><span>你的 Mac</span></div><div><span class="mint">~ %</span> 查看机器人状态<br><span class="dim">连接成功，下一步由你完成。</span><br><span class="mint">›</span> <b class="cursor">_</b></div></div><div class="art-caption">你来管理，它在远方运行。</div></div></section>
    <section class="stats-row"><div><span class="stat-icon">◷</span><p><strong>20 分钟</strong><small>每天完成一件小事</small></p></div><div><span class="stat-icon">▤</span><p><strong>7 个小课</strong><small>从认识环境到独立完成</small></p></div><div><span class="stat-icon">✳</span><p><strong>${total()} / 7 已掌握</strong><small>${realDone()?'已自行确认真实验收':'模拟练习与真实验收分别记录'}</small></p><div class="small-progress"><span style="width:${progress}%"></span></div></div></section>
    <section class="section"><div class="section-title"><div><p class="eyebrow">YOUR LEARNING PATH</p><h2>一条能走完的学习路线</h2></div><span class="quiet">不用背完所有命令，先学会做事。</span></div><div class="lesson-grid">${A.lessons.map((l,i)=>`<a class="lesson-card ${state.done.includes(i)?'complete':''}" href="#lesson/${i}/read"><div class="card-top"><span class="course-number">${label(i)}</span><span>${state.done.includes(i)?'✓ 已掌握':l.tag}</span></div><div class="lesson-icon">${l.icon}</div><h3>${e(l.title)}</h3><p>${e(l.subtitle)}</p><div class="card-bottom"><span>约 20 分钟 · 讲解 + 练习</span><b>↗</b></div></a>`).join('')}<div class="path-note"><span>✦</span><h3>学会之后，自己来。</h3><p>你能检查在线状态、完成扫码、判断故障，并验证机器人恢复回复。</p><a class="text-link" href="#lesson/6/read">看看最后的挑战 →</a></div></div></section>
    <section class="environment"><div><p class="eyebrow">先分清，谁在哪里</p><h2>一张属于你的环境地图</h2><p>点选一个角色，看看它负责什么。</p></div><div class="map"><div class="map-buttons"><button class="map-node selected" data-device="mac">⌘ <strong>你的 Mac</strong><small>输入命令 · 打开网页</small></button><span>SSH →</span><button class="map-node" data-device="server">▤ <strong>云服务器</strong><small>Ubuntu · Docker</small></button><span>连接 →</span><button class="map-node" data-device="qq">◉ <strong>QQ 与模型</strong><small>登录 · 收消息 · 回复</small></button></div><p id="map-explain" aria-live="polite">Mac 是你的管理入口。关闭 Mac 不会直接停止云端 QQbot。</p></div></section>
    <div class="bottom-note"><span>ℹ</span><p>这是学习网站。终端输出和扫码按钮均为模拟；真实操作在你自己的 Mac 上完成。无需在这里提供密码、密钥或 Token。</p></div>`;
  }
  function lesson(id,tab) {
    const l=A.lessons[id]; state.last=id; save();
    const tabs=[['read','01','看懂原理'],['practice','02','模拟练习'],['real','03','真实操作'],['quiz','04','检查掌握']];
    let body='';
    if(tab==='read') body=`<div class="reading-layout"><article class="paper"><p class="intro">${e(l.intro)}</p>${l.blocks.map(([t,b],i)=>`<section class="reading-block"><span>${label(i)}</span><div><h2>${e(t)}</h2><p>${e(b)}</p></div></section>`).join('')}<div class="takeaway"><span>✳ 记住这一句</span><p>${e(l.takeaway)}</p></div><div class="page-actions">${button('去模拟练习 →',`#lesson/${id}/practice`)}</div></article><aside class="lesson-aside"><div class="note-card"><p class="eyebrow">今天的小目标</p><h3>${e(l.title)}</h3><p>${e(l.subtitle)}</p><hr><p>学完不急着背命令，先用自己的话解释这一课。</p><a href="#reference">打开命令速查 ↗</a></div><div class="note-card plain"><h3>给第一次开始的你</h3><p>不理解的词，可以在命令速查里搜索。所有课程都可随时打开复习。</p></div></aside></div>`;
    if(tab==='practice') body=lab(id);
    if(tab==='real') body=`<div class="reading-layout"><article class="paper"><div class="notice"><strong>现在，请切换到你自己的 Mac</strong><p>下面是实操指引。勾选只代表你的个人确认，网站无法检测服务器。每条 remote.sh 命令都在 Mac 的 QQbot 项目目录执行。</p></div>${code('cd '+A.project)}<div class="real-steps">${l.real.map(([t,b],i)=>`<label class="real-step"><input type="checkbox" data-real="${id}-${i}" ${state.real[`${id}-${i}`]?'checked':''}><span><b>${i+1}. ${e(t)}</b><span>${e(b)}</span></span></label>`).join('')}</div>${l.challenge?'':`<h3>本课会用到的命令</h3>${l.commands.filter(c=>!c.startsWith('ssh ')).map(code).join('')}`}<p class="muted">如果服务已经正常，不必为了练习故意制造掉线或停止服务。可以先完成模拟，再在实际需要时运用。</p>${id===4?tokenHelp():''}<div id="real-result">${realStatus(id)}</div><div class="page-actions">${button('检查是否掌握 →',`#lesson/${id}/quiz`)}<button class="button secondary" data-action="print">打印实操清单</button></div></article><aside class="lesson-aside"><div class="note-card"><p class="eyebrow">遇到问题先停一下</p><h3>先看原因，再行动</h3><p>SSH 错误、QQ 未登录、模型不回复，需要不同的处理。</p><a href="#trouble">按现象找下一步 →</a></div></aside></div>`;
    if(tab==='quiz') body=`<article class="paper quiz-paper"><p class="intro">不用急着猜答案。选完后查看解释，答错可以重试。</p><form id="quiz-form" data-lesson="${id}">${l.quiz.map(([q,opts],i)=>`<fieldset><legend><span class="question-number">${label(i)}</span>${e(q)}</legend>${opts.map((opt,j)=>`<label class="quiz-option"><input type="radio" name="q${i}" value="${j}" required ${state.answers[id]?.[i]===j?'checked':''}><span>${e(opt)}</span></label>`).join('')}<div id="feedback-${i}" class="feedback" aria-live="polite"></div></fieldset>`).join('')}<button class="button primary" type="submit">检查我的答案 →</button></form><div id="lesson-completion">${completion(id)}</div></article>`;
    return `${header(`第 ${label(id)} 课 / 共 7 课 <span class="pill">约 20 分钟</span>`,e(l.title),e(l.subtitle))}<div class="tabs" role="navigation" aria-label="本课步骤">${tabs.map(([t,n,name])=>`<a class="tab ${t===tab?'selected':''}" href="#lesson/${id}/${t}" ${t===tab?'aria-current="step"':''}><span>${n}</span>${name}${t==='practice'&&state.practice[id]||t==='quiz'&&state.quiz[id]?' <b>✓</b>':''}</a>`).join('')}</div>${body}`;
  }
  function tokenHelp() { return `<details class="token-help"><summary>管理页要 Token，但我没有保存，怎么办？</summary><p>在 Mac 的第二个终端进入项目目录，完整复制并执行下面这段命令（包含最后一行 PY）。它通过既有 SSH 只读查看服务器的 WebUI 配置，并仅在你的终端显示 Token。网站不会执行或接收它。</p>${code(A.tokenCommand)}<p>将终端输出的 Token 复制到你自己的本机 WebUI 登录框，然后继续手机扫码。不要粘贴到学习网站或发给别人。若提示配置不存在、权限不足或 Token 为空，先停止，不修改或覆盖配置。</p></details>`; }
  function realStatus(id) { const l=A.lessons[id], n=l.real.filter((_,i)=>state.real[`${id}-${i}`]).length; return `<div class="real-summary">已自行确认 ${n} / ${l.real.length} 项${id===6&&n===l.real.length?' · ✳ 真实验收已由你确认完成！':''}</div>`; }
  function completion(id) { const pass=state.quiz[id]&&state.practice[id]; return `<div class="completion-box"><h3>${state.done.includes(id)?'✓ 这课已经掌握':pass?'练习和测验都通过了！':'完成两个检查，就能标记掌握'}</h3><p>${state.practice[id]?'✓':'○'} 模拟任务完成　${state.quiz[id]?'✓':'○'} 两道测验答对</p><p class="muted">真实操作清单独立记录，不会因为模拟通关而自动勾选。</p><button class="button primary" data-complete="${id}" ${pass?'':'disabled'}>${id===6?'完成学习路线 ✳':'掌握这课，继续下一课 →'}</button>${!state.practice[id]?`<a class="text-link" href="#lesson/${id}/practice">返回模拟练习</a>`:''}</div>`; }
  function lab(id=null) {
    const l=id===null?null:A.lessons[id];
    labLesson=id; sim=new A.Simulator(l?.scenario||'healthy'); historyIndex=0;
    return `${id===null?header('PRACTICE MAKES PROGRESS','在这里，放心试一试。','所有命令只在浏览器里模拟，不会连接服务器。可切换故障场景练习判断。'):''}<div class="lab-layout"><section class="terminal-panel"><div class="lab-toolbar"><span><i class="green-dot"></i> 模拟终端 <small>不连接真实服务器</small></span>${id===null?`<select id="scenario" aria-label="选择模拟场景"><option value="healthy">正常运行</option><option value="scan">QQ 等待扫码</option><option value="stopped">服务已停止</option><option value="model">QQ 在线，模型故障</option><option value="ssh">SSH 超时</option><option value="port">本机端口占用</option></select>`:`<span class="pill">${l.challenge?'独立挑战':l.tag}</span>`}</div><div class="terminal"><div class="terminal-tabs"><button class="selected" data-terminal="0">Mac 终端 A</button><button data-action="second-terminal">＋ 打开第二个终端</button><button class="terminal-clear" data-action="clear-terminal">清屏</button></div><div id="terminal-output" role="log" aria-label="模拟终端输出" aria-live="polite"><div class="terminal-welcome">服务器小课 · 模拟练习环境<br>输入 help 查看命令。先用 pwd 判断当前位置，再 cd 进入项目。<br><span class="dim">不要在此输入真实密码、Token 或密钥。</span></div></div><form id="terminal-form" autocomplete="off"><label id="terminal-prompt" for="terminal-input">${e(sim.prompt())}</label><div class="terminal-input-row"><span>›</span><input id="terminal-input" aria-label="模拟命令" placeholder="输入命令，按回车执行" spellcheck="false" autocapitalize="off" autocorrect="off"><button type="submit">执行 ↵</button></div></form><div class="terminal-footer"><span id="terminal-location">当前位置：Mac 本机</span><button data-action="interrupt">Control + C · 中断</button></div></div><div class="sim-controls"><button class="button secondary" data-action="scan">模拟手机扫码并确认</button><button class="button secondary" data-action="message">模拟发消息验证</button></div><p class="muted">扫码按钮只改变练习状态。真实登录要在 Mac 打开 WebUI，用机器人账号的手机 QQ 扫码。</p><div id="practice-result" aria-live="polite"></div></section><aside class="lab-guide"><div class="note-card"><p class="eyebrow">${l?'本课任务':'自由练习'}</p><h3>${l?l.challenge?'不给答案，也能完成':'每完成一步，就亮一格':'试着解决一个小问题'}</h3>${l?`<ol class="task-list">${l.tasks.map(([event,t])=>`<li data-task="${event}"><span>○</span>${e(t)}</li>`).join('')}</ol>`:'<p>先查看状态，根据结果决定：需要扫码、恢复服务，还是检查模型。</p><p>故障场景之间相互独立，切换会重新开始模拟。</p>'}${l?.challenge?'<details><summary>需要时再看命令提示</summary>'+hints(l)+'</details>':hints(l)}<button class="text-link reset-lab" data-action="reset-lab">重新开始本次模拟 ↺</button></div>${id!==null?`<a class="button secondary full" id="next-real" href="#lesson/${id}/real">去看真实操作清单 →</a>`:''}</aside></div>`;
  }
  function hints(l) { return `<div class="command-hints"><p>点击填入，按回车执行</p>${(l?.commands||['pwd','cd '+A.project,A.remote('status'),A.remote('webui'),A.remote('configure-login'),A.remote('start'),A.remote('backup')]).map(c=>`<button data-command="${e(c)}"><code>${e(c)}</code><span>↵</span></button>`).join('')}</div>`; }
  function reference() {
    return `${header('KEEP IT HANDY','想不起来，就来查。','不用背命令。先确认它在哪里执行、会产生什么影响。')}<div class="reference-layout"><section><div class="notice"><strong>这些命令在 Mac 的项目目录执行</strong><p>先进入项目；每条命令单独执行，不复制 % / $ 提示符。</p>${code('cd '+A.project)}</div>${[['status','查看状态','只读。先找服务状态，再读 live / ready，最后真实发消息验证。'],['webui','打开管理隧道','保持终端开启，在同一台 Mac 的浏览器打开 http://127.0.0.1:16099/webui/。用第二个终端执行其他命令。'],['configure-login','设置快捷登录','QQ 已通过手机确认后执行。它不能保证永久免扫码。'],['start','恢复运行','会启动服务；只在你确定需要运行时执行。随后查状态。'],['stop','停止服务','会停止云端机器人，并设置维护标记。日常掉线不要盲目使用。'],['backup','手动备份','会创建含私密配置的备份，按密钥文件保管。不会把备份下载到网站。']].map(([a,t,b])=>`<article class="command-card"><div><h3>${t}</h3><span class="pill ${a==='stop'?'amber':''}">${a==='status'?'只读':a==='stop'?'会停止机器人':'按需执行'}</span></div>${code(A.remote(a))}<p>${e(b)}</p></article>`).join('')}<article class="command-card"><h3>基础命令和快捷键</h3><dl class="basic-commands"><dt>pwd</dt><dd>显示当前目录</dd><dt>ls</dt><dd>列出目录内容</dd><dt>cd 路径</dt><dd>切换目录；cd .. 回上层；cd ~ 回主目录</dd><dt>exit</dt><dd>退出当前远程 shell，回到本机</dd><dt>Control + C</dt><dd>中断当前前台任务；关闭隧道不会直接停止机器人</dd><dt>Command + N</dt><dd>在 Mac 终端新开窗口；记得重新 cd 进入项目</dd></dl></article></section><aside><div class="note-card glossary"><p class="eyebrow">术语翻译器</p><h3>把技术词换成白话</h3><input type="search" id="glossary-search" placeholder="搜索 SSH、端口、容器…" aria-label="搜索术语"><div id="glossary-list">${glossary('')}</div></div><div class="note-card plain"><button class="button secondary full" data-action="print">打印当前速查表</button></div></aside></div>`;
  }
  function glossary(q) { const rows=A.glossary.filter(x=>x.join(' ').toLowerCase().includes(q.toLowerCase())); return rows.length?rows.map(([t,b])=>`<details><summary>${e(t)}</summary><p>${e(b)}</p></details>`).join(''):'<p class="muted">没有匹配的词，换个关键词试试。</p>'; }
  function trouble() {
    return `${header('ONE STEP AT A TIME','遇到问题，先找对那一层。','选一个与你看到的现象相近的问题。一次处理一件事，之后再检查状态。')}<div class="trouble-flow"><span>① Mac 与连接</span><b>→</b><span>② 服务器与程序</span><b>→</b><span>③ QQ 登录</span><b>→</b><span>④ 消息与模型</span></div><div class="trouble-list">${A.troubles.map(([t,err,desc,cmd],i)=>`<details class="trouble-card"><summary><span><strong>${e(t)}</strong><code>${e(err)}</code></span><b>＋</b></summary><div><p>${e(desc)}</p>${cmd?code(A.remote(cmd)):''}${i===6?tokenHelp():''}<a class="text-link" href="#lab">去模拟环境练一次 →</a></div></details>`).join('')}</div><div class="bottom-note"><span>✳</span><p>看到等待扫码，请本人确认登录；看到主机指纹异常，请先核对服务器身份。恢复前不删除数据，不重装系统。</p></div>`;
  }
  function sources() { return `${header('ABOUT THIS LITTLE COURSE','学的是你的环境，练的是自己的能力。','本课程依据项目现有运维入口编写，教学模拟不会读取或操作真实服务器。')}<article class="paper"><h2>内容依据</h2><p>课程环境依据 QQbot 4.0 的 README.md、docs/cloud.md、docs/v4.0.0.md 和 scripts/cloud/remote.sh，文档记录日期为 2026 年 10 月 17 日。真实环境如果升级，请重新核对命令与页面。</p><ul class="source-links"><li><a href="https://ubuntu.com/server/docs/tutorial/welcome-to-the-terminal/" target="_blank" rel="noreferrer">Ubuntu 官方：认识终端 ↗</a></li><li><a href="https://ubuntu.com/server/docs/how-to/security/openssh-server/" target="_blank" rel="noreferrer">Ubuntu 官方：OpenSSH ↗</a></li><li><a href="https://napneko.github.io/use/integration" target="_blank" rel="noreferrer">NapCat 官方：接入框架 ↗</a></li></ul><p>状态输出为缩短后的教学示例，字段与真实输出可能不同。网站未检测服务器当前运行状态。</p><h2>学习进度如何保存</h2><p>已掌握课程、模拟任务、测验和个人实操确认保存在当前浏览器的本地存储。更换浏览器或清除网站数据会丢失进度；不跨设备同步。你可以导出一份 JSON 记录留存。</p><p id="storage-detail">${storageOK?'当前浏览器允许保存进度。':'当前浏览器不能可靠保存，请导出记录。'}</p><div class="page-actions"><button class="button secondary" data-action="export">导出学习记录</button><button class="text-link danger" data-action="reset-progress">清空本机学习记录</button></div><h2>完成情况</h2><p>已掌握 ${total()} / 7 课。${realDone()?'最终真实验收已由你自行确认完成。':'最终真实验收尚未全部由你确认。'} 模拟练习和真实验收分别记录。</p><h2>管理页凭证</h2><p>WebUI Token 是私密管理凭证，课程不存储、不展示，也不提供公共默认值。如果你没有安全记录，第五课的真实操作页提供通过既有 SSH 在自己终端只读查看的命令。网站不会执行该命令或接收 Token。</p></article>`; }
  function render() {
    let [route,id,tab]=location.hash.slice(1).split('/'); route=route||'home';
    if(route==='lesson'&&/^\d+$/.test(id||'')&&A.lessons[Number(id)]) { id=Number(id); tab=['read','practice','real','quiz'].includes(tab)?tab:'read'; main.innerHTML=lesson(id,tab); $('#breadcrumb').textContent=`学习路线 / 第 ${label(id)} 课 / ${A.lessons[id].tag}`; }
    else { labLesson=null; sim=null; const views={home,lab:()=>lab(),reference,trouble,sources}; route=views[route]?route:'home'; main.innerHTML=views[route](); $('#breadcrumb').textContent='学习空间 / '+({home:'概览',lab:'终端练习场',reference:'命令速查',trouble:'遇到问题',sources:'内容与记录'}[route]); }
    nav(); document.title=(route==='lesson'?A.lessons[id].title:({home:'学习概览',lab:'终端练习场',reference:'命令速查',trouble:'遇到问题',sources:'内容与记录'}[route]))+' · 服务器小课';
    if(!storageOK) $('#save-status').textContent='浏览器未允许保存，请导出进度';
    window.scrollTo(0,0);
  }
  function output(text,command) { if(!$('#terminal-output')) return; if(text===null) $('#terminal-output').innerHTML=''; else { const line=document.createElement('div'); line.className='terminal-entry'; if(command) { const p=document.createElement('div');p.className='typed-command';p.textContent=command;line.append(p); } const pre=document.createElement('pre');pre.textContent=text;line.append(pre);$('#terminal-output').append(line); } $('#terminal-output').scrollTop=$('#terminal-output').scrollHeight; updateLab(); }
  function updateLab() {
    if(!sim||!$('#terminal-input')) return;
    $('#terminal-prompt').textContent=sim.prompt();
    const blocked=sim.tunnel&&sim.tunnelTerminal===sim.active;
    $('#terminal-input').disabled=blocked; $('#terminal-form button').disabled=blocked;
    $('#terminal-input').placeholder=blocked?'隧道正在运行，请打开第二个终端':'输入命令，按回车执行';
    $('#terminal-location').textContent=(sim.terminal.remote?'当前位置：Ubuntu 服务器':'当前位置：Mac 本机')+(sim.tunnel?' · 隧道开启':'');
    document.querySelectorAll('[data-terminal]').forEach(b=>b.classList.toggle('selected',Number(b.dataset.terminal)===sim.active));
    if(labLesson!==null) {
      const l=A.lessons[labLesson];
      document.querySelectorAll('[data-task]').forEach(el=>{const done=sim.events.has(el.dataset.task);el.classList.toggle('done',done);el.querySelector('span').textContent=done?'✓':'○';});
      if(l.tasks.every(([event])=>sim.events.has(event))) { state.practice[labLesson]=true;save();nav(); $('#practice-result').innerHTML='<div class="success-note">✓ 本课模拟任务完成！接下来去自己的 Mac 做实操。这里只记录模拟通过。</div>'; }
    }
  }
  document.addEventListener('submit',ev=>{
    if(ev.target.id==='terminal-form') { ev.preventDefault(); const raw=$('#terminal-input').value; const prompt=sim.prompt(); const result=sim.run(raw); $('#terminal-input').value='';historyIndex=sim.history.length;output(result,prompt+' '+raw); }
    if(ev.target.id==='quiz-form') {
      ev.preventDefault(); const id=Number(ev.target.dataset.lesson), form=new FormData(ev.target); let correct=0;
      state.answers[id]=A.lessons[id].quiz.map(([q,opts,answer,why],i)=> {const a=Number(form.get('q'+i)),ok=a===answer; correct+=ok?1:0;const f=$('#feedback-'+i);f.className='feedback '+(ok?'good':'wrong');f.textContent=(ok?'✓ 答对了。':'再想想。')+why;return a;});
      if(correct===A.lessons[id].quiz.length) state.quiz[id]=true;save(); $('#lesson-completion').innerHTML=completion(id);nav();
    }
  });
  document.addEventListener('change',ev=>{
    if(ev.target.dataset.real) {const id=Number(ev.target.dataset.real.split('-')[0]);state.real[ev.target.dataset.real]=ev.target.checked;save();$('#real-result').innerHTML=realStatus(id);}
    if(ev.target.id==='scenario') {sim=new A.Simulator(ev.target.value);$('#terminal-output').textContent='已重置为所选的教学场景。先用 pwd 与 cd 定位，再检查状态。';document.querySelector('.terminal-tabs').innerHTML='<button class="selected" data-terminal="0">Mac 终端 A</button><button data-action="second-terminal">＋ 打开第二个终端</button><button class="terminal-clear" data-action="clear-terminal">清屏</button>';updateLab();}
  });
  document.addEventListener('input',ev=>{if(ev.target.id==='glossary-search') $('#glossary-list').innerHTML=glossary(ev.target.value);});
  document.addEventListener('keydown',ev=>{
    if(!sim||!$('#terminal-input')||!main.contains(ev.target)) return;
    if(ev.ctrlKey&&ev.key.toLowerCase()==='c') {ev.preventDefault();output(sim.interrupt());}
    if(ev.target.id==='terminal-input'&&(ev.key==='ArrowUp'||ev.key==='ArrowDown')) {ev.preventDefault();historyIndex=Math.max(0,Math.min(sim.history.length,historyIndex+(ev.key==='ArrowUp'?-1:1)));ev.target.value=sim.history[historyIndex]||'';}
  });
  document.addEventListener('click',async ev=>{
    const el=ev.target.closest('button,[data-device]');if(!el)return;
    if(el.dataset.copy!==undefined) {try {await navigator.clipboard.writeText(el.dataset.copy);toast('命令已复制，请在自己的 Mac 终端执行');}catch{const range=document.createRange();range.selectNodeContents(el.previousElementSibling);getSelection().removeAllRanges();getSelection().addRange(range);toast('已选中命令，请按 Command + C 复制');}}
    if(el.dataset.command!==undefined) {if($('#terminal-input').disabled){toast('先打开第二个终端，或结束当前隧道');return;}$('#terminal-input').value=el.dataset.command;$('#terminal-input').focus();}
    if(el.dataset.complete!==undefined) {const id=Number(el.dataset.complete);if(!state.practice[id]||!state.quiz[id])return;if(!state.done.includes(id))state.done.push(id);save();if(id<6)location.hash=`lesson/${id+1}/read`;else{location.hash='home';toast('七课学习完成！真实验收请按自己的实际情况确认。');}}
    if(el.dataset.device) {document.querySelectorAll('[data-device]').forEach(n=>n.classList.toggle('selected',n===el));$('#map-explain').textContent={mac:'Mac 是你的管理入口。关闭 Mac 不会直接停止云端 QQbot。',server:'云服务器运行 Ubuntu。Docker 中的 NapCat 与 QQbot 各自负责登录连接和消息处理。',qq:'手机 QQ 负责本人扫码确认；另一个 QQ 用来验收回复。模型 API 负责生成回答，QQ 在线不保证模型可用。'}[el.dataset.device];}
    if(el.dataset.terminal!==undefined){sim.active=Number(el.dataset.terminal);output('已切换到 Mac 终端 '+(sim.active?'B':'A')+'。');}
    switch(el.dataset.action) {
      case 'second-terminal': output(sim.openSecond());if(!document.querySelector('[data-terminal="1"]')){el.insertAdjacentHTML('beforebegin','<button data-terminal="1">Mac 终端 B</button>');}updateLab();break;
      case 'interrupt':output(sim.interrupt());break;
      case 'scan':output(sim.scan());break;
      case 'message':output(sim.message());break;
      case 'clear-terminal':output(null);break;
      case 'reset-lab': {const scenario=labLesson===null?$('#scenario').value:A.lessons[labLesson].scenario||'healthy';sim=new A.Simulator(scenario);$('#terminal-output').textContent='本次模拟已重新开始。已保存的学习进度不受影响。';const b=document.querySelector('[data-terminal="1"]');if(b)b.remove();$('#practice-result').textContent='';updateLab();break;}
      case 'print':window.print();break;
      case 'export': {const blob=new Blob([JSON.stringify({course:'服务器小课',version:1,exportedAt:new Date().toISOString(),progress:state},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='服务器小课-学习记录.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('学习记录已导出；这是记录副本，不会自动跨设备同步');break;}
      case 'reset-progress':if(confirm('仅清空此浏览器的学习记录？这不会影响 QQbot 或服务器。')){state=blank();save();render();toast('本机学习记录已清空');}break;
    }
  });
  window.addEventListener('hashchange',()=>{render();main.focus({preventScroll:true});});
  render();
})();
